#include <jni.h>
#include <EGL/egl.h>
#include <GLES/gl.h>
#include <AL/al.h>
#include <AL/alc.h>
#include <android/asset_manager.h>
#define STB_IMAGE_IMPLEMENTATION
#define STB_IMAGE_STATIC
#define STBI_ONLY_JPEG
#define STBI_ONLY_PNG
#define STBI_ONLY_BMP
#define STBI_ONLY_GIF
#define STBI_NO_STDIO
#include "stb_image.h"
extern "C" JNIEXPORT jint JNICALL JNI_OnLoad(JavaVM*,void*) { return JNI_VERSION_1_6; }
// Link-time dependency probe only; no device execution.
extern "C" JNIEXPORT int hm_android_dependency_probe(AAssetManager* assets) {
 auto display=eglGetDisplay(EGL_DEFAULT_DISPLAY);
 auto device=alcOpenDevice(nullptr);
 auto asset=AAssetManager_open(assets,"RawData/WeaponInfo.mch",AASSET_MODE_BUFFER);
 int x=0,y=0,c=0;const unsigned char invalid[1]={0};
 auto pixels=stbi_load_from_memory(invalid,1,&x,&y,&c,4);stbi_image_free(pixels);
 auto error=glGetError();auto audio=alGetError();
 if(asset)AAsset_close(asset);if(device)alcCloseDevice(device);
 return int(display!=EGL_NO_DISPLAY)+int(error)+int(audio);
}
